const SNIPPETS={
 "Hardship reasons":["a temporary loss of income when my employer reduced hours from {{EVENT_DATE}}","a medical emergency in my household in {{EVENT_DATE}}","a Permanent Change of Station move in {{EVENT_DATE}}, during which my mail and autopay were interrupted","a deployment from {{EVENT_DATE}}, when I had limited access to banking","a divorce/separation finalized {{EVENT_DATE}} that changed my household income","an error by my bank that was later reversed (documentation enclosed)"],
 "What changed":["I have since enrolled in automatic payments on every account.","My income has stabilized at $\{{AMOUNT}} per month and all accounts are current.","I have built ____ months of reserves and paid down my revolving balances.","I now work from a single primary bank account to avoid missed payments."],
 "Military":["My current enlistment runs through {{EVENT_DATE}}; a statement of service is enclosed.","My BAH at the new duty station will be $\{{AMOUNT}} per the DoD BAH calculator.","I receive VA disability compensation of $\{{AMOUNT}} per month, which is non-taxable and permanent.","My spouse will occupy the property within 60 days of closing while I complete my deployment.","A specific power of attorney and alive-and-well letter are enclosed."],
 "Dispute phrasing":["Please provide the name, address and telephone number of the furnisher you contacted.","If the item cannot be verified, delete it and send me an updated copy of my report.","I have enclosed documentation; a telephone or automated verification is not sufficient.","Please do not treat this dispute as frivolous — the enclosed records are specific to the item disputed."],
 "Closing lines":["Thank you for your prompt attention to this matter.","I am available at {{PHONE}} or {{EMAIL}} should you need anything further.","Please respond in writing within 30 days as required."],
};
const TOKENS=LETTER_FIELDS.map(f=>f[0]).concat(["BUREAU"]);
let letterEdits=store.get("letterEdits",{});
PAGE.letters={ html:()=>`
<div class="tabs" id="ltabs"><button data-t="dispute">Dispute letters (${DISPUTE_LETTERS.length})</button><button data-t="loe">Letters of explanation (${LOE_LETTERS.length})</button></div>
<div class="card" style="margin-top:14px"><div class="row"><div style="flex:2;min-width:260px"><label for="lsel">Template</label><select id="lsel"></select></div><div style="flex:1;min-width:160px"><label for="lq">Filter the list</label><input type="text" id="lq" placeholder="Search…"></div><div id="lbwrap" style="min-width:170px"><label for="lb">Bureau</label><select id="lb">${Object.entries(BUREAUS).map(([k,b])=>`<option value="${k}">${b.name.split(",")[0]}</option>`).join("")}</select></div></div>
 <div id="lmeta" style="margin-top:8px"></div></div>
<div class="grid g12"><div><div class="card"><h3>Borrower details <span class="sub">saved locally · flow into every token</span></h3><div class="form" style="grid-template-columns:1fr 1fr">${LETTER_FIELDS.map(([k,l])=>`<div class="${k==="DETAIL"?"wide":""}"><label>${l}</label>${k==="DETAIL"?`<textarea id="lf_${k}" rows="3">${esc(letterForm[k])}</textarea>`:`<input type="text" id="lf_${k}" value="${esc(letterForm[k])}">`}</div>`).join("")}</div></div>
 <div class="card"><h3>Guardrails</h3><ul class="sm mut" style="margin:0 0 0 18px;padding:0"><li>Dispute only inaccurate, incomplete, unverifiable or obsolete items. Accurate negatives → goodwill (D31), pay-for-delete (D30) or time.</li><li>No CPNs, no new EIN for personal credit, no "dispute everything".</li><li>Active disputes can block automated underwriting; during a loan prefer a rapid rescore.</li><li>${BUREAU_NOTE}</li><li>LOEs: one issue per letter, facts and dates, no blame, what changed, signed and dated.</li></ul></div></div>
 <div><div class="card"><h3>Tailor the body <span class="sub">plug-and-play: click a field to insert it at the cursor · edits save per template</span></h3>
  <div class="row sm" id="ltoks" style="margin-bottom:6px"></div>
  <div class="row" style="margin-bottom:6px"><select id="lsnipcat" style="width:auto">${Object.keys(SNIPPETS).map(k=>`<option>${k}</option>`).join("")}</select><select id="lsnip" style="flex:1;min-width:200px"></select><button class="btn ghost sm" id="lins">Insert phrase</button><span class="sp"></span><button class="btn ghost sm" id="lreset">Reset to original</button></div>
  <textarea id="lbody" rows="12" style="font-family:Georgia,serif;font-size:13px;line-height:1.5"></textarea></div>
  <div class="card"><h3 id="ltitle">Preview</h3><div class="row" id="lctl" style="margin:8px 0"></div><pre class="code" id="lprev" style="max-height:none;background:var(--panel);border:1px solid var(--line);font-family:Georgia,serif;font-size:13px;padding:36px 48px"></pre></div></div></div>`,
 mount(){ let tab=store.get("ltab","dispute"), cur=null, bureau=store.get("lbureau","EFX"); $("#lb").value=bureau;
  const lib=()=>tab==="dispute"?DISPUTE_LETTERS:LOE_LETTERS, cats=()=>tab==="dispute"?DISPUTE_CATS:LOE_CATS;
  const bodyOf=L=>letterEdits[L.id]??L.body;
  const withBody=L=>({...L,body:bodyOf(L)});
  const paras=(L,b)=>tab==="dispute"?disputeParagraphs(withBody(L),b||bureau,letterForm):loeParagraphs(withBody(L),letterForm);
  const fillSel=()=>{const q=$("#lq").value.toLowerCase(); $("#lsel").innerHTML=`<option value="">— choose a ${tab==="dispute"?"dispute letter":"letter of explanation"} —</option>`+cats().map(c=>{const items=lib().filter(l=>l.cat===c&&(!q||JSON.stringify(l).toLowerCase().includes(q)));return items.length?`<optgroup label="${esc(c)}">${items.map(l=>`<option value="${l.id}" ${cur?.id===l.id?"selected":""}>${l.id} — ${esc(l.title)}${letterEdits[l.id]?" ✎":""}</option>`).join("")}</optgroup>`:""}).join("")};
  const setTab=t=>{tab=t;store.set("ltab",t);$$("#ltabs button").forEach(b=>b.classList.toggle("on",b.dataset.t===t));cur=null;const last=store.get("lcur_"+t,null);if(last)cur=lib().find(l=>l.id===last)||null;fillSel();$("#lbwrap").style.display=t==="dispute"?"":"none";show()};
  const readForm=()=>{LETTER_FIELDS.forEach(([k])=>letterForm[k]=$("#lf_"+k).value);store.set("letterForm",letterForm)};
  const snips=()=>{$("#lsnip").innerHTML=SNIPPETS[$("#lsnipcat").value].map(s=>`<option>${esc(s)}</option>`).join("")}; snips(); $("#lsnipcat").onchange=snips;
  const insertAt=(txt)=>{const ta=$("#lbody");const s=ta.selectionStart??ta.value.length,e=ta.selectionEnd??s;ta.value=ta.value.slice(0,s)+txt+ta.value.slice(e);ta.selectionStart=ta.selectionEnd=s+txt.length;ta.focus();ta.dispatchEvent(new Event("input"))};
  $("#ltoks").innerHTML=`<span class="mut">Insert field:</span>`+TOKENS.map(t=>`<button class="btn ghost sm" data-tok="${t}">{{${t}}}</button>`).join(""); $$("[data-tok]").forEach(b=>b.onclick=()=>insertAt("{{"+b.dataset.tok+"}}"));
  $("#lins").onclick=()=>insertAt(($("#lbody").value&&!/\n$/.test($("#lbody").value)?"\n\n":"")+$("#lsnip").value);
  $("#lbody").oninput=()=>{if(!cur)return;const v=$("#lbody").value;if(v===cur.body)delete letterEdits[cur.id];else letterEdits[cur.id]=v;store.set("letterEdits",letterEdits);fillSel();preview()};
  $("#lreset").onclick=()=>{if(!cur)return;delete letterEdits[cur.id];store.set("letterEdits",letterEdits);$("#lbody").value=cur.body;fillSel();preview();toast("Original template restored")};
  const preview=()=>{if(!cur){$("#lprev").textContent="Choose a template from the dropdown above.";return}const P=paras(cur);$("#lprev").innerHTML=P.map(p=>p.b?`<b>${esc(p.t)}</b>`:esc(p.t)).join("\n")};
  const show=()=>{ if(!cur){$("#ltitle").textContent="Preview";$("#lmeta").innerHTML=`<div class="mut sm">${lib().length} templates in ${cats().length} categories. Pick one, fill the borrower details, tailor the body, then download as Word or PDF.</div>`;$("#lctl").innerHTML="";$("#lbody").value="";preview();return}
   store.set("lcur_"+tab,cur.id); $("#ltitle").textContent=`${cur.id} — ${cur.title}`; $("#lbody").value=bodyOf(cur);
   $("#lmeta").innerHTML=tab==="dispute"?`<div class="sm"><b>When to use:</b> ${esc(cur.situation)}</div><div class="sm"><b>Legal basis:</b> ${esc(cur.basis)}</div>${cur.notUse?`<div class="tag warn" style="white-space:normal;display:block">Do not use: ${esc(cur.notUse)}</div>`:""}${cur.tips?`<div class="mut sm">Tip: ${esc(cur.tips)}</div>`:""}<div class="mut sm">Addressed to: ${cur.to==="bureau"?"credit bureau (select above)":cur.to}</div>`:`<div class="sm"><b>When:</b> ${esc(cur.when)}</div><div class="sm"><b>What the underwriter needs:</b> ${esc(cur.uw)}</div>${cur.tip?`<div class="mut sm">Tip: ${esc(cur.tip)}</div>`:""}`;
   const base=`${cur.id}-${slug(cur.title)}${tab==="dispute"&&cur.to==="bureau"?"-"+bureau:""}`;
   $("#lctl").innerHTML=`<button class="btn sm" id="ldoc">⬇ Word (.docx)</button><button class="btn sm" id="lpdf">⬇ PDF</button>${tab==="dispute"&&cur.to==="bureau"?`<button class="btn ghost sm" id="l3">All 3 bureaus (.zip: Word + PDF)</button>`:""}<button class="btn ghost sm" id="lcopy">Copy text</button><span class="sp"></span><button class="btn ghost sm" id="lall">Entire ${tab==="dispute"?"dispute":"LOE"} library (.zip)</button>`;
   $("#ldoc").onclick=()=>saveFile(base+".docx",docxBytes(paras(cur)));
   $("#lpdf").onclick=()=>saveFile(base+".pdf",pdfBytes(paras(cur)));
   $("#lcopy").onclick=()=>copy(paras(cur).map(p=>p.t).join("\n"));
   $("#l3")&&($("#l3").onclick=()=>saveFile(`${cur.id}-${slug(cur.title)}-all-bureaus.zip`,makeZip(Object.keys(BUREAUS).flatMap(b=>[{name:`${cur.id}-${b}.docx`,data:docxBytes(paras(cur,b))},{name:`${cur.id}-${b}.pdf`,data:pdfBytes(paras(cur,b))}]))));
   $("#lall").onclick=()=>{const files=lib().flatMap(L=>{const dir=L.cat.replace(/[^a-z0-9]+/gi,"_");const nm=`${L.id}-${slug(L.title)}`;if(tab==="dispute"&&L.to==="bureau")return Object.keys(BUREAUS).flatMap(b=>{const P=disputeParagraphs(withBody(L),b,letterForm);return [{name:`${dir}/${nm}-${b}.docx`,data:docxBytes(P)},{name:`${dir}/${nm}-${b}.pdf`,data:pdfBytes(P)}]});const P=tab==="dispute"?disputeParagraphs(withBody(L),bureau,letterForm):loeParagraphs(withBody(L),letterForm);return [{name:`${dir}/${nm}.docx`,data:docxBytes(P)},{name:`${dir}/${nm}.pdf`,data:pdfBytes(P)}]});saveFile(`VANESSA-${tab==="dispute"?"dispute-letters":"letters-of-explanation"}.zip`,makeZip(files));toast(`${files.length} files packaged (Word + PDF)`)};
   preview(); };
  $$("#ltabs button").forEach(b=>b.onclick=()=>setTab(b.dataset.t)); $("#lq").oninput=fillSel; $("#lsel").onchange=()=>{cur=lib().find(l=>l.id===$("#lsel").value)||null;show()}; $("#lb").onchange=()=>{bureau=$("#lb").value;store.set("lbureau",bureau);show()};
  $$("[id^=lf_]").forEach(e=>e.oninput=()=>{readForm();preview()}); setTab(tab); }};

/* ======== VA TOOLKIT ======== */
PAGE.va={ html:()=>`<div class="tabs" id="vtabs">${[["ff","Funding fee"],["ent","Entitlement"],["res","Residual income"],["irrrl","IRRRL tester"],["coe","Eligibility (COE)"],["bah","BAH vs mortgage"],["fees","Allowable fees"],["mpr","MPRs"],["docs","Document checklists"],["timeline","VA purchase timeline"]].map(([k,t])=>`<button data-t="${k}">${t}</button>`).join("")}</div><div id="vbody" style="margin-top:14px"></div>`,
 mount(){ const T={
  ff:{html:()=>`<div class="grid g12"><div class="card"><h3>VA funding fee (2026)</h3><div class="form" style="grid-template-columns:1fr 1fr">${numf("f_price","Price $",550000,5000)}${numf("f_down","Down %",0,.5)}${sel("f_type","Loan type",[["purchase","Purchase / construction"],["cashout","Cash-out refinance"],["irrrl","IRRRL"]],"purchase")}${sel("f_use","Entitlement use",[["first","First use"],["sub","Subsequent use"]],"first")}<div class="wide">${chkf("f_ex","Exempt (VA disability compensation, Purple Heart, qualifying surviving spouse)")}</div><div class="wide">${chkf("f_fin","Finance the fee into the loan",true)}</div></div></div><div><div class="grid g2" id="fk" style="margin-top:0"></div><div class="card"><h3>Who is exempt</h3><ul class="sm" style="margin:0 0 0 18px">${VA.fundingFee.exempt.map(x=>`<li>${x}</li>`).join("")}</ul><p class="mut sm">Pending disability claim at closing? Pay the fee; request a refund if the rating's effective date precedes closing (LOE L78). The fee is tax-deductible as mortgage insurance for premiums paid on/after Jan 1 2026 (OBBBA; itemizers, phase-out $100–110k AGI).</p></div></div></div>`,
   mount(){const go=()=>{const price=val("f_price"),down=val("f_down")/100,type=$("#f_type").value,sub=$("#f_use").value==="sub",ex=$("#f_ex").checked,fin=$("#f_fin").checked;const base=price*(1-down);const pct=vaFundingFee(down,sub,ex,type);const fee=base*pct/100;const total=fin?base+fee:base;$("#fk").innerHTML=[["Base loan",money(base)],["Funding fee %",pct.toFixed(2)+"%"],["Funding fee $",money(fee)],[fin?"Total loan with fee":"Loan (fee paid in cash)",money(total)],["Added P&I at "+market.vapar30.toFixed(3)+"%",fin?money2(pmt(fee,market.vapar30/100,360))+"/mo":"$0"],["Tier",type==="irrrl"?"IRRRL 0.50%":type==="cashout"?(sub?"3.30% subsequent":"2.15% first"):down<.05?(sub?"3.30% subsequent, <5% down":"2.15% first, <5% down"):down<.10?"1.50% (5–9.99% down)":"1.25% (10%+ down)"]].map(([k,v])=>`<div class="card kpi"><div class="k">${k}</div><div class="v" style="font-size:20px">${v}</div></div>`).join("")};$$("#vbody input,#vbody select").forEach(e=>e.oninput=go);go()}},
  ent:{html:()=>`<div class="grid g12"><div class="card"><h3>Entitlement &amp; down payment</h3><div class="form" style="grid-template-columns:1fr 1fr">${numf("e_price","Purchase price $",650000,5000)}${sel("e_lim","County loan limit",[["832750","Baseline $832,750"],["1104000","San Diego $1,104,000"],["1249125","High-cost ceiling $1,249,125"]],"832750")}${numf("e_used","Entitlement currently used $",80000,1000)}<div class="wide">${chkf("e_full","Full entitlement (no prior VA loan, or prior loan paid off & restored)",false)}</div></div><p class="mut sm">Partial entitlement: VA guarantees 25% of the county limit minus entitlement in use; the veteran covers 25% of any loan amount above 4× the remaining entitlement. Entitlement used ≈ 25% of the prior loan amount (see COE). Restore by paying off and selling, a one-time restoration if the loan is paid off but the home kept, or substitution by an assuming veteran.</p></div><div><div class="grid g2" id="ek" style="margin-top:0"></div><div class="card"><p class="sm" id="enote"></p><p class="mut sm">Jumbo VA: with full entitlement there is no VA limit; lenders cap 0-down around $1.5–2M then 89.99% LTV. Second-tier entitlement lets a PCS'ing veteran keep the first home as a rental.</p></div></div></div>`,
   mount(){const go=()=>{const r=vaEntitlement(val("e_price"),+$("#e_lim").value,val("e_used"),$("#e_full").checked);$("#ek").innerHTML=[["Remaining entitlement",isFinite(r.remaining)?money(r.remaining):"Full"],["Max loan with $0 down",isFinite(r.maxNoDown)?money(r.maxNoDown):"No VA limit"],["Down payment required",money(r.down)],["VA guaranty on this loan",money(Math.min(r.guaranty,val("e_price")*.25))]].map(([k,v])=>`<div class="card kpi"><div class="k">${k}</div><div class="v" style="font-size:20px">${v}</div></div>`).join("");$("#enote").textContent=r.note};$$("#vbody input,#vbody select").forEach(e=>e.oninput=go);go()}},
  res:{html:()=>`<div class="grid g12"><div class="card"><h3>Residual income</h3><div class="form" style="grid-template-columns:1fr 1fr">${sel("r_state","Property state",["CA","NV","AZ","IL","FL","TX","WA","CO","NY","GA","NC","VA","OR","UT"],"NV")}${numf("r_fam","Family size",3,1)}${numf("r_loan","Loan amount $",450000,5000)}${numf("r_gross","Gross monthly income $",7200,50)}${numf("r_nontax","…of which non-taxable (BAH/BAS/VA disability) $",2200,50)}${numf("r_piti","Proposed PITI $",2900,10)}${numf("r_hoa","HOA $/mo",0,10)}${numf("r_sqft","Living area sq ft",1800,50)}${numf("r_debts","Other monthly debts $",500,10)}${numf("r_cs","Child support / alimony paid $",0,10)}${numf("r_cc","Child care $",0,10)}${numf("r_st","State income tax rate % (NV/TX/FL/WA = 0)",0,.5)}</div><p class="mut sm">Taxes are estimated from brackets + FICA; underwriters use the actual withholding on the LES/pay stub. Maintenance &amp; utilities at $0.14/sq ft (verify current). When DTI exceeds 41%, residual must be 120% of the table.</p></div><div><div class="grid g2" id="rk" style="margin-top:0"></div><div class="card"><h3>Residual table — ${"loan ≥ $80k"}</h3><table><thead><tr><th>Family</th><th>Northeast</th><th>Midwest</th><th>South</th><th>West</th></tr></thead><tbody>${[1,2,3,4,5].map(i=>`<tr><td>${i}</td>${["Northeast","Midwest","South","West"].map(r=>`<td>$${VA.residual[r][i-1]}</td>`).join("")}</tr>`).join("")}<tr><td>6+</td><td colspan="4" class="mut">add $80 per member (max 7)</td></tr></tbody></table></div></div></div>`,
   mount(){const go=()=>{const r=vaResidual({state:$("#r_state").value,family:val("r_fam"),loan:val("r_loan"),grossMonthly:val("r_gross"),nonTaxableMonthly:val("r_nontax"),piti:val("r_piti"),hoa:val("r_hoa"),sqft:val("r_sqft"),otherDebts:val("r_debts"),childSupport:val("r_cs"),childcare:val("r_cc"),stateTaxRate:val("r_st")/100});$("#rk").innerHTML=[["Region",r.region],["Required residual",money(r.req)+(r.needs120?" → 120% = "+money(r.reqAdj):"")],["DTI",(r.dti*100).toFixed(1)+"%"+(r.needs120?" (>41% → 120% rule)":"")],["Est. taxes/mo",money(r.taxesMonthly)],["Maintenance/utilities",money(r.maint)],["Residual income",`<span class="${r.pass?"up":"dn"}">${money(r.net)}</span>`],["Result",r.pass?"✔ PASS — cushion "+money(r.cushion):"✘ SHORT by "+money(-r.cushion)+" — see LOE L68 compensating factors / S13 seller debt payoff"]].map(([k,v])=>`<div class="card kpi"><div class="k">${k}</div><div class="v" style="font-size:18px">${v}</div></div>`).join("")};$$("#vbody input,#vbody select").forEach(e=>e.oninput=go);go()}},
  irrrl:{html:()=>`<div class="grid g12"><div class="card"><h3>IRRRL eligibility tester</h3><div class="form" style="grid-template-columns:1fr 1fr">${numf("i_days","Days since first payment due",400,1)}${numf("i_pmts","Monthly payments made",13,1)}${sel("i_ot","Existing loan",[["fixed","Fixed"],["arm","ARM"]],"fixed")}${sel("i_nt","New loan",[["fixed","Fixed"],["arm","ARM"]],"fixed")}${numf("i_or","Existing rate %",6.75,.125)}${numf("i_nr","New rate %",5.875,.125)}${numf("i_op","Existing P&I $",2594,1)}${numf("i_np","New P&I $",2366,1)}${numf("i_cc","Closing costs excl. funding fee/prepaids $",5200,100)}${numf("i_oterm","Old term (yrs)",30,1)}${numf("i_nterm","New term (yrs)",30,1)}<div class="wide">${chkf("i_late","30-day late in the last 12 months")}</div><div class="wide">${chkf("i_occ","Veteran previously occupied the home",true)}</div></div></div><div><div class="card"><div id="ik"></div></div><div class="card"><h3>Refi Hunter rule of thumb</h3><p class="sm">Outreach when (current − achievable) ≥ 0.75% (strong) / ≥ 0.50% (minimum). Re-run the whole queue when VA par drops ≥ 0.125%. The ISA program (SOP §7.6) buckets borrowers: (a) seasoned + gap met, (b) gap met, not seasoned, (c) gap not met.</p></div></div></div>`,
   mount(){const go=()=>{const r=irrrlTest({daysSinceFirstDue:val("i_days"),monthsSinceFirstPayment:Math.floor(val("i_days")/30),paymentsMade:val("i_pmts"),oldType:$("#i_ot").value,newType:$("#i_nt").value,oldRate:val("i_or"),newRate:val("i_nr"),oldPI:val("i_op"),newPI:val("i_np"),closingCosts:val("i_cc"),oldTerm:val("i_oterm"),newTerm:val("i_nterm"),lates12:$("#i_late").checked,occupiedBefore:$("#i_occ").checked});$("#ik").innerHTML=`<div class="tag ${r.pass?"good":"bad"}" style="font-size:14px">${r.pass?"✔ Likely IRRRL-eligible":"✘ Not yet eligible"}</div><div class="mut sm" style="margin:6px 0">Monthly savings ${money2(r.monthlySave)} · recoupment ${isFinite(r.recoup)?r.recoup.toFixed(1)+" months":"n/a"}</div>${r.tests.map(t=>`<div class="row" style="padding:6px 0;border-bottom:1px solid var(--line)"><span class="${t[1]?"up":"dn"}">${t[1]?"✔":"✘"}</span><span class="sp sm">${esc(t[0])}</span></div>`).join("")}<p class="mut sm">38 U.S.C. §3709 / VA Circular 26-19-22 — verify current. Funding fee 0.50% (waived if exempt). Lender overlays may add a minimum score.</p>`};$$("#vbody input,#vbody select").forEach(e=>e.oninput=go);go()}},
  coe:{html:()=>`<div class="grid g12"><div class="card"><h3>Eligibility quick check</h3><div class="form" style="grid-template-columns:1fr 1fr">${sel("c_status","Status",[["veteran","Veteran (separated)"],["active","Active duty"],["guard","National Guard"],["reserve","Reserve"]],"veteran")}${numf("c_days","Active-duty days (Title 10)",730,1)}${numf("c_years","Years in Selected Reserve/Guard",0,1)}${numf("c_t32","Title 32 days (Guard)",0,1)}${sel("c_disch","Discharge",[["honorable","Honorable / General"],["oth","Other than honorable"],["dishonorable","Dishonorable"]],"honorable")}<div class="wide">${chkf("c_spouse","Surviving spouse")}</div></div><div id="ck2" style="margin-top:8px"></div></div><div class="card"><h3>Getting the COE</h3><ol class="sm" style="margin:0 0 0 18px"><li>Lender pulls it instantly in WebLGY (most cases).</li><li>Veteran: VA.gov eBenefits, or VA Form 26-1880 by mail.</li><li>Active duty: statement of service on letterhead (name, SSN/DoD ID, DOB, entry date, lost time, command).</li><li>Guard/Reserve: NGB-22/NGB-23 or points statement + DD-214 for any Title 10 periods.</li><li>Surviving spouse: VA Form 26-1817 + veteran's DD-214 (and DIC award).</li><li>Partial entitlement shown → run the Entitlement tab.</li></ol><p class="mut sm">Character-of-discharge: an OTH discharge may be eligible after a VA determination; LOE L75.</p></div></div>`,
   mount(){const go=()=>{const r=vaEligibility({status:$("#c_status").value,branch:$("#c_status").value,activeDays:val("c_days"),years:val("c_years"),title32Days:val("c_t32"),discharge:$("#c_disch").value,spouse:$("#c_spouse").checked});$("#ck2").innerHTML=`<div class="tag ${r.likely?"good":"warn"}" style="font-size:14px">${r.likely?"Likely eligible — confirm on the COE":"Needs VA review"}</div>${r.checks.map(c=>`<div class="row" style="padding:6px 0;border-bottom:1px solid var(--line)"><span class="${c[1]?"up":"dn"}">${c[1]?"✔":"✘"}</span><span class="sp sm">${esc(c[0])}</span></div>`).join("")}`};$$("#vbody input,#vbody select").forEach(e=>e.oninput=go);go()}},
  bah:{html:()=>`<div class="grid g12"><div class="card"><h3>BAH vs mortgage — Nellis AFB (MHA NV361)</h3><div class="form" style="grid-template-columns:1fr 1fr">${sel("b_grade","Pay grade",Object.keys(VA.nellisBAH),"E-5")}${sel("b_dep","Dependents",[["0","With dependents"],["1","Without dependents"]],"0")}${numf("b_price","Home price $",420000,5000)}${numf("b_rate","VA rate %",market.vapar30,.125)}${numf("b_tax","Property tax %",0.6,.05)}${numf("b_ins","Insurance $/yr",1500,100)}</div><p class="mut sm">BAH figures are planning estimates from the marketing plan — verify at the DoD BAH calculator before publishing. Nevada: no state income tax; disabled-veteran property tax exemptions.</p></div><div><div class="grid g2" id="bk2" style="margin-top:0"></div><div class="card"><h3>Seminar talking point</h3><p class="sm" id="btalk"></p></div></div></div>`,
   mount(){const go=()=>{const bah=VA.nellisBAH[$("#b_grade").value][+$("#b_dep").value],price=val("b_price"),rate=val("b_rate"),loan=price*(1+2.15/100),pi=pmt(loan,rate/100,360),tax=price*val("b_tax")/100/12,ins=val("b_ins")/12,piti=pi+tax+ins;$("#bk2").innerHTML=[["Monthly BAH",money(bah)],["P&I (fee financed)",money2(pi)],["Est. PITI",money2(piti)],["BAH covers",Math.round(bah/piti*100)+"%"],["Gap / surplus",(bah-piti>=0?"+":"")+money2(bah-piti)]].map(([k,v])=>`<div class="card kpi"><div class="k">${k}</div><div class="v" style="font-size:20px">${v}</div></div>`).join("");$("#btalk").textContent=`An ${$("#b_grade").value} ${+$("#b_dep").value?"without":"with"} dependents at Nellis receives about ${money(bah)}/month in BAH. On a ${money(price)} home with $0 down, the estimated PITI is ${money(piti)} — BAH covers ${Math.round(bah/piti*100)}%. Instead of paying a landlord, that allowance builds equity. (Illustrative; not a rate quote.)`};$$("#vbody input,#vbody select").forEach(e=>e.oninput=go);go()}},
  fees:{html:()=>`<div class="grid g2"><div class="card"><h3>Veteran MAY pay (allowable)</h3><ul class="sm" style="margin:0 0 0 18px">${VA.allowableFees.map(f=>`<li>${f}</li>`).join("")}</ul></div><div class="card"><h3>Veteran may NOT pay (non-allowable — seller, lender or agent must cover)</h3><ul class="sm" style="margin:0 0 0 18px">${VA.nonAllowable.map(f=>`<li>${f}</li>`).join("")}</ul><p class="mut sm">If the lender charges the 1% flat fee, it covers all lender origination costs; itemized lender fees instead must total ≤1%. VA Pamphlet 26-7 Ch. 8 — verify current.</p></div></div>`,mount(){}},
  mpr:{html:()=>`<div class="card"><h3>Minimum Property Requirements — pre-offer checklist</h3>${VA.mprs.map((m,i)=>`<label class="chk" style="padding:6px 0;border-bottom:1px solid var(--line)"><input type="checkbox" data-m="${i}"> ${m}</label>`).join("")}<p class="mut sm" style="margin-top:8px">Tidewater: if the appraiser expects value below contract, the point of contact gets 2 business days to submit comps (LOE L80). Reconsideration of Value after the NOV. VA appraisals cannot be 'ordered around' — only the VA assigns appraisers.</p></div>`,mount(){}},
  docs:{html:()=>`<div class="grid g2">${Object.entries(VA.docs).map(([k,v])=>`<div class="card"><h3>${k}</h3>${v.map((d,i)=>`<label class="chk" style="padding:4px 0"><input type="checkbox"> ${d}</label>`).join("")}<div class="row" style="margin-top:8px"><button class="btn ghost sm" data-copy="${esc(k)}">Copy checklist</button></div></div>`).join("")}</div>`,mount(){$$("[data-copy]").forEach(b=>b.onclick=()=>copy(VA.docs[b.dataset.copy].map(d=>"☐ "+d).join("\n")))}},
  timeline:{html:()=>`<div class="card"><h3>VA purchase timeline — what the ISA tracks</h3><div class="steps">${["Day 0 — Consultation + COE pull (WebLGY)","Day 1–3 — Application, credit, TBD underwriting approval","Offer — VA escape clause, 4%/costs structure, non-allowables assigned","Contract +1 — Appraisal ordered through VA portal (10–14 days typical; Tidewater window 2 days)","Contract +3 — Disclosures (TRID 3-day), lock decision via Market Intel lean","Contract +7–10 — Conditions out (LOEs from the Letter Desk)","NOV — Value notice; ROV if needed","CTC — Clear to close; CD 3 business days before signing","Closing — Funding fee, 1% cap check on CD, alive-and-well if deployed","+30 days — Review ask; +6 months — IRRRL watch starts (210 days)"].map((s,i)=>`<span class="step ${i<3?"done":""}">${s}</span>`).join("")}</div></div>`,mount(){}},
 };
  const tabs=$$("#vtabs button"); const show=k=>{store.set("vtab",k);tabs.forEach(b=>b.classList.toggle("on",b.dataset.t===k));$("#vbody").innerHTML=T[k].html();T[k].mount()}; tabs.forEach(b=>b.onclick=()=>show(b.dataset.t)); show(store.get("vtab","ff")); }};

