PAGE.marketing={ html:()=>`
<div class="card"><h3>${esc(MARKETING.event.name)} <span class="sub">${esc(MARKETING.event.date)}</span></h3><div class="row"><span class="tag">${esc(MARKETING.event.where)}</span><span class="tag">Budget ${money(MARKETING.event.budget)} · Steven ${money(MARKETING.event.stevenShare)}</span><span class="tag good">${esc(MARKETING.event.leadSplit)}</span></div><p style="font-size:15px;margin:10px 0 0"><b>Hook:</b> “${esc(MARKETING.event.hook)}”</p></div>
<div class="card"><h3>KPI scorecard <span class="sub">targets from the plan · actuals are sample until Zoho/GA4 connect</span></h3><div style="overflow:auto"><table><thead><tr><th>Channel</th><th>Metric</th><th>Target</th><th>Actual</th><th style="width:160px">Progress</th></tr></thead><tbody>${MARKETING.kpis.map(k=>{const num=parseFloat(String(k[2]).replace(/[^0-9.]/g,""))||0;const p=k[3]==null?0:Math.min(100,k[3]/num*100);return `<tr><td>${k[0]}</td><td>${k[1]}</td><td>${k[2]}</td><td>${k[3]==null?"<span class='mut'>—</span>":k[3]}</td><td><div class="bar"><i style="width:${p}%"></i></div></td></tr>`}).join("")}</tbody></table></div></div>
<div class="grid g2"><div class="card"><h3>Funnel calculator</h3><div class="form" style="grid-template-columns:1fr 1fr">${numf("m_spend","Ad spend $",3300,100)}${numf("m_reg","Registrations",92,1)}${numf("m_show","Show rate %",45,1)}${numf("m_app","Attendee → application %",12,1)}${numf("m_close","Application → closed %",40,1)}${numf("m_rev","Revenue per closed loan $",6500,250)}</div><div class="grid g3" id="mk" style="margin-top:10px"></div></div>
 <div class="card"><h3>Buyer personas</h3><table><thead><tr><th>Persona</th><th>Product</th><th>Channel</th></tr></thead><tbody>${MARKETING.personas.map(p=>`<tr>${p.map(c=>`<td>${esc(c)}</td>`).join("")}</tr>`).join("")}</tbody></table></div></div>
<div class="grid g2"><div class="card"><h3>Channels &amp; budget</h3><table><thead><tr><th>Channel</th><th>Plan</th><th>Cost</th></tr></thead><tbody>${MARKETING.channels.map(c=>`<tr><td><b>${esc(c[0])}</b></td><td class="sm">${esc(c[1])}</td><td>${esc(c[2])}</td></tr>`).join("")}</tbody></table></div>
 <div class="card"><h3>Follow-up &amp; conversion (W4/W5/W22)</h3><table><tbody>${MARKETING.followUp.map(f=>`<tr><td><b>${esc(f[0])}</b></td><td class="sm">${esc(f[1])}</td><td><span class="tag">${esc(f[2])}</span></td></tr>`).join("")}</tbody></table><h3 style="margin-top:12px">Recurring webinars</h3>${MARKETING.webinars.map(w=>`<div class="row" style="padding:4px 0"><span class="sp">${esc(w[0])}</span><span class="mut sm">${esc(w[1])}</span></div>`).join("")}</div></div>
<div class="grid g2"><div class="card"><h3>Master timeline</h3><table><thead><tr><th>Window</th><th>Event track</th><th>Business development</th></tr></thead><tbody>${MARKETING.timeline.map(t=>`<tr>${t.map(c=>`<td class="sm">${esc(c)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>
 <div class="card"><h3>Compliance framework</h3><ul class="sm" style="margin:0 0 0 18px">${MARKETING.compliance.map(c=>`<li>${esc(c)}</li>`).join("")}</ul><h3 style="margin-top:12px">Stack</h3>${MARKETING.stack.map(s=>`<div class="row" style="padding:3px 0"><span class="mut sm" style="width:130px">${s[0]}</span><span class="sm">${s[1]}</span></div>`).join("")}</div></div>`,
 mount(){const go=()=>{const spend=val("m_spend"),reg=val("m_reg"),att=reg*val("m_show")/100,apps=att*val("m_app")/100,closed=apps*val("m_close")/100,rev=closed*val("m_rev");$("#mk").innerHTML=[["Attendees",Math.round(att)],["Applications",apps.toFixed(1)],["Closed loans",closed.toFixed(1)],["Cost / registration",money(spend/reg)],["Blended CPA",closed?money(spend/closed):"—"],["ROAS",spend?(rev/spend).toFixed(1)+"x":"—"]].map(([k,v])=>`<div class="card kpi"><div class="k">${k}</div><div class="v" style="font-size:20px">${v}</div></div>`).join("")};$$("[id^=m_]").forEach(e=>e.oninput=go);go()}};

/* ======== EA / ISA OPS ======== */
PAGE.isa={ html:()=>`
<div class="grid g21"><div class="card"><h3>Speed-to-lead <span class="sub">5-minute SLA during coverage hours</span></h3><div class="row"><button class="btn sm" id="newlead">New lead arrived</button><b id="sla" style="font-size:28px;font-variant-numeric:tabular-nums">—</b><span class="sp"></span><button class="btn good sm" id="contacted">Contacted ✔</button></div><div class="mut sm" id="slalog" style="margin-top:8px"></div></div>
 <div class="card"><h3>Non-negotiables</h3><ul class="sm" style="margin:0 0 0 18px">${SOP.nonNeg.map(n=>`<li>${esc(n)}</li>`).join("")}</ul></div></div>
<div class="grid g3">${[["Start of day","startOfDay"],["New lead SOP (every lead)","leadSop"],["End of day","endOfDay"]].map(([t,k])=>`<div class="card"><h3>${t} <span class="sub"><button class="btn ghost sm" data-clear="${k}">reset</button></span></h3>${SOP[k].map((s,i)=>`<label class="chk" style="padding:5px 0;border-bottom:1px solid var(--line)"><input type="checkbox" data-ck="${k}:${i}"> <span class="sm">${esc(s)}</span></label>`).join("")}</div>`).join("")}</div>
<div class="grid g2"><div class="card"><h3>Qualification script (permitted)</h3><table><tbody>${SOP.qualification.map(q=>`<tr><td><b>${q[0]}</b></td><td>“${esc(q[1])}”</td></tr>`).join("")}</tbody></table><h3 style="margin-top:12px">Never answer independently</h3><ul class="sm" style="margin:0 0 0 18px">${SOP.notAnswer.map(n=>`<li>${esc(n)}</li>`).join("")}</ul></div>
 <div class="card"><h3>Four-layer leverage model</h3><table><thead><tr><th>Layer</th><th>Owns</th><th>Never</th></tr></thead><tbody>${SOP.layers.map(l=>`<tr><td><b>${esc(l[0])}</b></td><td class="sm">${esc(l[1])}</td><td class="sm mut">${esc(l[2])}</td></tr>`).join("")}</tbody></table><p class="mut sm">Before anything reaches Steven: Can Layer 3 draft it? Can Layer 2 execute it? Does it legally require Layer 1?</p></div></div>
<div class="grid g2"><div class="card"><h3>Mortgage pipeline stages (Zoho + Arive)</h3><div class="steps">${SOP.stages.map(s=>`<span class="step">${esc(s)}</span>`).join("")}</div><h3 style="margin-top:12px">IRRRL rate-drop program (§7.6)</h3><div class="sm"><b>Criteria:</b> ${SOP.irrrlProgram.criteria.join(" · ")}</div><div class="sm" style="margin-top:4px"><b>Buckets:</b> ${SOP.irrrlProgram.buckets.join(" · ")}</div><div class="sm" style="margin-top:4px"><b>Sources:</b> ${SOP.irrrlProgram.sources.join(" · ")}</div><div class="tag warn" style="white-space:normal;display:block;margin-top:6px">${esc(SOP.irrrlProgram.boundary)}</div></div>
 <div class="card"><h3>Escalate to Steven immediately</h3><ul class="sm" style="margin:0 0 0 18px">${SOP.escalate.map(e=>`<li>${esc(e)}</li>`).join("")}</ul><h3 style="margin-top:12px">Weekly capacity audit</h3><ol class="sm" style="margin:0 0 0 18px">${SOP.capacityAudit.map(e=>`<li>${esc(e)}</li>`).join("")}</ol></div></div>`,
 mount(){ const cks=store.get("isaChecks",{}); $$("[data-ck]").forEach(c=>{c.checked=!!cks[c.dataset.ck];c.onchange=()=>{cks[c.dataset.ck]=c.checked;store.set("isaChecks",cks)}}); $$("[data-clear]").forEach(b=>b.onclick=()=>{Object.keys(cks).filter(k=>k.startsWith(b.dataset.clear+":")).forEach(k=>delete cks[k]);store.set("isaChecks",cks);route()});
  let t0=store.get("slaStart",null),iv; const tick=()=>{if(!t0){$("#sla").textContent="—";return}const s=Math.floor((Date.now()-t0)/1000);$("#sla").textContent=`${String(Math.floor(s/60)).padStart(2,"0")}:${String(s%60).padStart(2,"0")}`;$("#sla").style.color=s>300?"var(--bad)":s>180?"var(--warn)":"var(--good)"}; iv=setInterval(tick,1000); cleanups.push(()=>clearInterval(iv)); tick();
  const log=store.get("slaLog",[]); const paintLog=()=>$("#slalog").innerHTML=log.slice(-5).reverse().map(l=>`${l}<br>`).join("");paintLog();
  $("#newlead").onclick=()=>{t0=Date.now();store.set("slaStart",t0);tick()}; $("#contacted").onclick=()=>{if(!t0)return;const s=Math.round((Date.now()-t0)/1000);log.push(`${new Date().toLocaleTimeString()} — contacted in ${Math.floor(s/60)}m ${s%60}s ${s<=300?"✔ within SLA":"✘ SLA missed"}`);store.set("slaLog",log);t0=null;store.set("slaStart",null);tick();paintLog()}; }};

/* ======== ZOHO CRM ======== */
PAGE.zoho={ html:()=>`
<div class="card"><h3>Zoho CRM — mortgage system of record <span class="sub">SOP §4.1 / §4.5 · paired with Arive</span></h3>
 <div class="grid g3" style="margin-top:0"><div class="card kpi" style="box-shadow:none"><div class="k">Connection</div><div class="v" style="font-size:16px">${esc(ZOHO.status.account)}</div></div><div class="card kpi" style="box-shadow:none"><div class="k">API access</div><div class="v" style="font-size:16px;color:var(--bad)">${esc(ZOHO.status.scopes)}</div></div><div class="card kpi" style="box-shadow:none"><div class="k">Scopes needed</div><div class="v" style="font-size:13px" class="mono">${esc(ZOHO.status.needed)}</div></div></div>
 <div class="row" style="margin-top:10px"><button class="btn sm" id="ztest">Test connection (via n8n / edge function)</button><button class="btn ghost sm" id="zsync">Run full sync (Z1–Z7)</button><span class="mut sm">Credentials never live in this page — the dashboard calls your n8n webhook or Supabase edge function, which hold the Zoho OAuth tokens.</span></div><div class="steps" id="zsteps">${ZOHO.workflows.map(w=>`<span class="step" data-id="${w[0]}">${w[0]} ${esc(w[1])}</span>`).join("")}</div></div>
<div class="grid g2"><div class="card"><h3>Go-live checklist</h3>${ZOHO.checklist.map((c,i)=>`<label class="chk" style="padding:5px 0;border-bottom:1px solid var(--line)"><input type="checkbox" data-z="${i}"> <span class="sm">${esc(c)}</span></label>`).join("")}</div>
 <div class="card"><h3>Module ↔ dashboard field mapping</h3><table><thead><tr><th>Zoho module</th><th>Dashboard / Supabase</th><th>Fields</th></tr></thead><tbody>${ZOHO.modules.map(m=>`<tr><td><b>${m[0]}</b></td><td class="sm">${esc(m[1])}</td><td class="sm mono">${esc(m[2])}</td></tr>`).join("")}</tbody></table><h3 style="margin-top:12px">Stage map (SOP 17 → Kanban 6)</h3>${ZOHO.stageMap.map(s=>`<div class="row sm" style="padding:3px 0"><span class="sp">${esc(s[0])}</span><span class="tag">${esc(s[1])}</span></div>`).join("")}</div></div>
<div class="card"><h3>Sync workflows</h3>${ZOHO.workflows.map(w=>`<details><summary>${w[0]} — ${esc(w[1])} ${w[4]?'<span class="tag warn">human approval</span>':""}</summary><div class="mut sm">Trigger: ${esc(w[2])}</div><div class="steps">${w[3].split(" › ").map(s=>`<span class="step">${esc(s)}</span>`).join("")}</div></details>`).join("")}<div class="mut sm">n8n nodes: ${ZOHO.n8nNodes.join(" → ")}</div></div>
<div class="card"><h3>Supabase Edge Function — zoho-sync <span class="sub"><button class="btn ghost sm" id="zcopy">Copy code</button></span></h3><pre class="code" id="zcode">${esc(ZOHO.edgeFunction)}</pre></div>
<div class="card"><h3>Sync log</h3><div id="zlog" class="mono sm"></div></div>`,
 mount(){ const cks=store.get("zohoChecks",{}); $$("[data-z]").forEach(c=>{c.checked=!!cks[c.dataset.z];c.onchange=()=>{cks[c.dataset.z]=c.checked;store.set("zohoChecks",cks)}});
  const log=store.get("zlog",["2026-10-18 23:10 UTC — Composio probe: ZOHO_LIST_MODULES / GET Leads / GET Deals → 403 NO_PERMISSION (CRM scopes missing)"]); const paint=()=>$("#zlog").innerHTML=log.slice(-12).reverse().map(l=>esc(l)+"<br>").join(""); paint();
  const add=l=>{log.push(`${new Date().toISOString().slice(0,16).replace("T"," ")} UTC — ${l}`);store.set("zlog",log);paint()};
  $("#zcopy").onclick=()=>copy(ZOHO.edgeFunction);
  $("#ztest").onclick=async()=>{try{if(settings.sbUrl&&settings.sbKey){const r=await fetch(settings.sbUrl.replace(/\/$/,"")+"/functions/v1/zoho-sync",{method:"POST",headers:{apikey:settings.sbKey,Authorization:"Bearer "+settings.sbKey,"Content-Type":"application/json"},body:JSON.stringify({op:"list",module:"Leads"})});const t=await r.text();add(`edge zoho-sync list Leads → HTTP ${r.status} ${t.slice(0,80)}`);toast(`zoho-sync: HTTP ${r.status}`)}else if(settings.n8n){const r=await fetch(settings.n8n.replace(/\/$/,"")+"/webhook/zoho-sync",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({op:"list",module:"Leads"})});add(`n8n /webhook/zoho-sync → HTTP ${r.status}`);toast(`n8n: HTTP ${r.status}`)}else{add("test skipped — no Supabase or n8n URL in Settings");toast("Add Supabase or n8n URL in Settings first")}}catch(e){add("test failed — "+e.message);toast(e.message,5000)}};
  $("#zsync").onclick=async()=>{const st=$$("#zsteps .step");st.forEach(s=>s.className="step");for(const s of st){s.classList.add("run");await new Promise(r=>setTimeout(r,450));s.classList.replace("run","done")}add("full sync simulated (Z1–Z7) — enable after scopes are granted");fireWorkflow("Z1",{})}; }};
